sys_script_include.script:
var EscRecordCreation = Class.create();
EscRecordCreation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    executeEscalationSubflow: function() {
        gs.info('[ESC SERVER LOG] Running escalation subflow execution script via Toolkit handoff.');

        try {
            // 1. Gather parameters passed from the workspace client modal layer
            var helpRequested   = this.getParameter('sysparm_help_requested');
            var supervisorAction = this.getParameter('sysparm_supervisor_action');
            var supervisorGroup  = this.getParameter('sysparm_supervisor_group'); // Contains the group Sys ID
            var interactionId   = this.getParameter('sysparm_interaction');

            gs.info('[ESC SERVER LOG] Parameters verified -> Interaction: ' + interactionId + ' | Group SysID: ' + supervisorGroup + ' | Action: ' + supervisorAction);

            // 2. Map fields to exactly match your escalation subflow schema inputs
            var inputs = {};
            inputs['help_requested']     = helpRequested; 
            inputs['supervisor_action']  = supervisorAction; 
            inputs['supervisor_group_sys_id']   = supervisorGroup; 
            inputs['interaction_sys_id'] = interactionId; 

            gs.info('[ESC SERVER LOG] Triggering Flow Runner Engine for: x_snc_pab_ee_tkit.create_a_escalation_activity');

            // 3. Execute Synchronously in the foreground pipeline block
            var result = sn_fd.FlowAPI.getRunner()
                .subflow('x_snc_pab_ee_tkit.create_a_escalation_activity')
                .inForeground()
                .withInputs(inputs)
                .run();

            var outputs = result.getOutputs();
            var esc_activity_notes = outputs['esc_activity_notes'] || '';

            gs.info('[ESC SERVER LOG] Execution complete. Subflow output notes: ' + esc_activity_notes);

            return JSON.stringify({ 
                status: 'success', 
                notes: esc_activity_notes 
            });

        } catch (ex) {
            var message = ex.getMessage ? ex.getMessage() : ex.message;
            gs.error('[ESC SERVER ERROR] Fatal escalation subflow exception: ' + message);
            return JSON.stringify({ status: 'error', message: message });
        }
    },

    type: 'EscRecordCreation'
});
